package com.kai.automusic;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import org.json.*;
public class PlayerService extends Service{MediaPlayer m,standby; String standbyUri=""; boolean standbyReady=false,fading=false; long fadeStart; int manualFadeMs=0; boolean manualPending=false; int deck=0;android.content.SharedPreferences p;int index=0,fail=0;boolean ready=false,want=false;String status="รอการชาร์จ";BroadcastReceiver power=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(Intent.ACTION_POWER_CONNECTED.equals(i.getAction())&&p.getBoolean("auto",true)){launch();play();}else if(Intent.ACTION_POWER_DISCONNECTED.equals(i.getAction())&&p.getBoolean("unplug",true))pause();}};
 Handler timer=new Handler(Looper.getMainLooper());Runnable checkpoint=new Runnable(){public void run(){remember();mixTick();timer.postDelayed(this,200);}};void remember(){if(m!=null&&ready)try{if(m.isPlaying()&&m.getCurrentPosition()>1000)fail=0;p.edit().putInt("position",m.getCurrentPosition()).putInt("duration",m.getDuration()).apply();}catch(Exception e){}}void launch(){if(p.getBoolean("launch",true))try{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));}catch(Exception e){}}public void onCreate(){super.onCreate();p=getSharedPreferences("music",0);index=p.getInt("index",0);deck=p.getInt("deck",0);if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("music","ระบบเล่นเพลงอัตโนมัติ",NotificationManager.IMPORTANCE_LOW));IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_POWER_CONNECTED);f.addAction(Intent.ACTION_POWER_DISCONNECTED);registerReceiver(power,f);timer.postDelayed(checkpoint,3000);}
 Notification notification(){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"music"):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Kai Auto Music").setContentText(status).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();}void update(String s){status=s;p.edit().putString("playerStatus",s).putBoolean("playing",s.startsWith("กำลังเล่นเพลงที่")).apply();getSystemService(NotificationManager.class).notify(1,notification());}
 public int onStartCommand(Intent i,int flags,int id){startForeground(1,notification());String a=i==null?"ARM":i.getAction();if("POWER".equals(a)){if(p.getBoolean("auto",true)){launch();play();}}else if("BOOT".equals(a)){launch();Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(p.getBoolean("bootPlay",true)||(battery!=null&&battery.getIntExtra("plugged",0)!=0&&p.getBoolean("auto",true)))play();}else if("ARM".equals(a)){p.edit().putBoolean("armed",true).apply();Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null&&battery.getIntExtra("plugged",0)!=0&&p.getBoolean("auto",true))play();}else if("PLAY".equals(a))play();else if("PAUSE".equals(a))pause();else if("RESET".equals(a)){release();want=false;index=p.getInt("index",0);p.edit().putInt("position",0).apply();update("หยุดชั่วคราว");}else if("SELECT".equals(a)){fail=0;p.edit().putBoolean("stopAfter",false).apply();index=i.getIntExtra("index",0);p.edit().putInt("position",0).apply();want=true;load();}else if("MIX3".equals(a)){if(!fading&&m!=null&&ready&&want&&planned()>=0){manualPending=true;mixTick();}}else if("MIX".equals(a)){if(standbyReady&&!fading&&m!=null&&want){standby.seekTo(Math.min(p.getInt("cueMs",0),Math.max(0,standby.getDuration()-1000)));standby.start();fading=true;fadeStart=SystemClock.elapsedRealtime();}}else if("SEEK".equals(a)){clearStandby();if(m!=null)m.setVolume(1,1);if(m!=null&&ready){m.seekTo(i.getIntExtra("ms",0));}}else if("PREV".equals(a)){fail=0;p.edit().putBoolean("stopAfter",false).apply();int n=songs().length();if(n>0){index=(p.getInt("index",index)+n-1)%n;p.edit().putInt("position",0).apply();want=true;load();}}else if("NEXT".equals(a)){fail=0;advance(true);}return START_STICKY;}
 JSONArray songs(){try{return new JSONArray(p.getString("songs","[]"));}catch(Exception e){return new JSONArray();}}void play(){want=true;fail=0;if(m!=null){if(ready){m.start();update("กำลังเล่นเพลงที่ "+(index+1));}return;}load();}void pause(){manualPending=false;clearStandby();if(m!=null)try{m.setVolume(1,1);}catch(Exception e){}remember();want=false;if(m!=null&&ready&&m.isPlaying())m.pause();update("หยุดชั่วคราว");}void release(){manualPending=false;clearStandby();p.edit().putInt("audioSession",-1).apply();p.edit().putBoolean("playing",false).apply();if(m!=null){m.release();m=null;}ready=false;}
 void load(){release();update("กำลังโหลดเพลง");JSONArray a=songs();if(a.length()==0){update("ไม่มีเพลงในเพลย์ลิสต์");return;}index=Math.max(0,Math.min(index,a.length()-1));p.edit().putInt("index",index).putInt("nextIndex",a.length()>1?(index+1+new java.util.Random().nextInt(a.length()-1))%a.length():index).apply();try{if(a.getString(index).startsWith("https://")){skipError();return;}m=new MediaPlayer();p.edit().putInt("audioSession",m.getAudioSessionId()).apply();m.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());m.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);m.setDataSource(this,Uri.parse(a.getString(index)));m.setOnPreparedListener(x->{ready=true;if(p.getBoolean("resume",true)){int pos=p.getInt("position",0);if(pos>0&&pos<x.getDuration())x.seekTo(pos);}if(want){x.start();update("กำลังเล่นเพลงที่ "+(index+1));}});m.setOnCompletionListener(x->completed(x));m.setOnErrorListener((x,w,e)->{skipError();return true;});m.prepareAsync();}catch(Exception e){skipError();}}
 void clearStandby(){if(standby!=null){try{standby.release();}catch(Exception e){}standby=null;}standbyReady=false;fading=false;manualFadeMs=0;standbyUri="";p.edit().putInt("mixPercent",0).apply();}
 int repeatMode(){return Math.max(0,Math.min(2,p.getInt("repeatMode",p.getBoolean("repeat",true)?2:0)));}int planned(){JSONArray a=songs();int n=a.length(),i=p.getInt("index",index);if(n<2||p.getBoolean("stopAfter",false))return -1;String selected=p.getString("manualNext","");for(int j=0;j<n;j++)if(j!=i&&a.optString(j).equals(selected))return j;if(repeatMode()==1)return -1;if(repeatMode()==0)return i+1<n?i+1:-1;int next=p.getBoolean("shuffle",false)?p.getInt("nextIndex",-1):i+1;if(next>=n){if(!p.getBoolean("repeat",true)&&!p.getBoolean("nonstop",true))return -1;next=0;}return next>=0&&next<n&&next!=i?next:-1;}
 void mixTick(){if(m==null||!ready||!want)return;try{int next=planned();String uri=next<0?"":songs().optString(next);p.edit().putInt("deck",deck).putString("deckNext",uri).apply();if(uri.isEmpty()||uri.startsWith("https://")){clearStandby();m.setVolume(1,1);return;}if(!uri.equals(standbyUri)){clearStandby();m.setVolume(1,1);standbyUri=uri;standby=new MediaPlayer();standby.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());standby.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);standby.setDataSource(this,Uri.parse(uri));standby.setVolume(0,0);standby.setOnPreparedListener(x->{if(x==standby)standbyReady=true;});standby.setOnErrorListener((x,w,e)->{if(x==standby){clearStandby();if(m!=null)m.setVolume(1,1);}return true;});standby.prepareAsync();}int ms=manualFadeMs>0?manualFadeMs:Math.max(500,p.getInt("fadeMs",5000));if(standbyReady&&!fading&&(manualPending||(p.getBoolean("autoDj",true)&&m.getDuration()-m.getCurrentPosition()<=ms))){manualFadeMs=manualPending?3000:0;manualPending=false;ms=manualFadeMs>0?manualFadeMs:ms;standby.seekTo(Math.min(p.getInt("cueMs",0),Math.max(0,standby.getDuration()-1000)));standby.start();fading=true;fadeStart=SystemClock.elapsedRealtime();}if(fading){float f=Math.min(1f,(SystemClock.elapsedRealtime()-fadeStart)/(float)ms);p.edit().putInt("mixPercent",(int)(f*100)).apply();m.setVolume(1-f,1-f);standby.setVolume(f,f);if(f>=1||!m.isPlaying())promote(next);}}catch(Exception e){clearStandby();if(m!=null)try{m.setVolume(1,1);}catch(Exception ignored){}}}
 void promote(int next){if(standby==null||!standbyReady||next<0)return;MediaPlayer old=m;m=standby;standby=null;standbyReady=false;fading=false;manualFadeMs=0;manualPending=false;standbyUri="";old.release();index=next;deck=1-deck;m.setVolume(1,1);m.setOnCompletionListener(x->completed(x));m.setOnErrorListener((x,w,e)->{if(x==m)skipError();return true;});p.edit().putInt("index",index).putInt("deck",deck).putInt("mixPercent",0).remove("manualNext").putInt("cueMs",0).putInt("audioSession",m.getAudioSessionId()).putInt("position",m.getCurrentPosition()).putInt("nextIndex",songs().length()>1?(index+1+new java.util.Random().nextInt(songs().length()-1))%songs().length():index).apply();update("กำลังเล่นเพลงที่ "+(index+1));}
 void completed(MediaPlayer x){if(x!=m)return;if(p.getBoolean("stopAfter",false)){p.edit().putBoolean("stopAfter",false).putInt("position",0).apply();want=false;release();update("หยุดเมื่อเพลงจบแล้ว");}else if(fading&&standbyReady&&planned()>=0)promote(planned());else advance(false);}
 void skipError(){release();if(p.getBoolean("stopAfter",false)){p.edit().putBoolean("stopAfter",false).apply();want=false;update("เพลงเปิดไม่ได้ จึงหยุดตามคำสั่ง");return;}if(++fail>=songs().length()){want=false;update("ไม่มีไฟล์ที่เล่นได้");return;}p.edit().putInt("position",0).apply();index=(p.getInt("index",index)+1)%songs().length();new Handler(Looper.getMainLooper()).post(()->{if(want)load();});}void advance(boolean manual){index=p.getInt("index",index);int n=songs().length();if(n==0){release();return;}p.edit().putInt("position",0).apply();if(manual){want=true;p.edit().putBoolean("stopAfter",false).apply();}else fail=0;if(!manual&&!want)return;if(!manual&&repeatMode()==1){load();return;}int override=-1;String selected=p.getString("manualNext","");for(int j=0;j<n;j++)if(j!=index&&songs().optString(j).equals(selected))override=j;if(override>=0){index=override;p.edit().remove("manualNext").putInt("position",p.getInt("cueMs",0)).putInt("cueMs",0).apply();}else if((manual||repeatMode()==2)&&p.getBoolean("shuffle",false)&&n>1){int planned=p.getInt("nextIndex",-1);index=planned>=0&&planned<n&&planned!=index?planned:(index+1+new java.util.Random().nextInt(n-1))%n;}else if(index+1>=n&&!manual&&repeatMode()==0){release();want=false;index=0;update("เล่นครบเพลย์ลิสต์แล้ว");return;}else index=(index+1)%n;deck=1-deck;p.edit().putInt("deck",deck).apply();load();}public IBinder onBind(Intent i){return null;}public void onDestroy(){remember();timer.removeCallbacks(checkpoint);unregisterReceiver(power);release();super.onDestroy();}}